var EXTRA=[{"dot": "gray", "j": "SICOT J", "h": "Nervo safeno nel LCA: più disturbi sensitivi con due tendini prelevati", "v": "Studio prospettico osservazionale a sei mesi; la differenza è significativa ma per la maggior parte dei pazienti non ha ostacolato la vita quotidiana; non randomizzato.", "pmid": "42878391", "doi": "10.1051/sicotj/2026051", "temi": ["LCA", "nervo safeno", "prelievo hamstring"]}, {"dot": "gray", "j": "Orthop Surg", "h": "LCA all-inside con rinforzo di sutura: nessuna rottura a due anni", "v": "Coorte retrospettiva senza controllo, in Malesia; gli autori stessi la dichiarano preliminare e utile solo a formulare ipotesi.", "pmid": "42878690", "doi": "10.1111/os.70442", "temi": ["LCA all-inside", "internal brace", "innesto"]}, {"dot": "gray", "j": "Arch Orthop Trauma Surg", "h": "Tunnel tibiale del LCA: verifica mediolaterale con riferimento alla notch", "v": "Serie unica validata con TC e RM, tunnel vicino all'impronta nativa; senza confronto né esiti clinici.", "pmid": "42867698", "doi": "10.1007/s00402-026-06442-w", "temi": ["LCA", "tunnel tibiale", "TC"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "TKA a cerniera rotante: sopravvivenza simile in primaria e in revisione", "v": "Coorte retrospettiva monocentrica senza gruppo di confronto; gli autori avvertono che le complicanze non si attribuiscono con certezza al vincolo dell'impianto.", "pmid": "42843681", "doi": "10.1016/j.arth.2026.09.042", "temi": ["TKA a cerniera", "revisione", "vincolo"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Radice mediale transtibiale: sutura a croce con centralizzazione senza nodi", "v": "Nota tecnica con video; nessun dato su pazienti nell'abstract.", "pmid": "42871408", "doi": "10.1002/atn2.70324", "temi": ["radice meniscale", "transtibiale", "centralizzazione"]}, {"dot": "gray", "j": "Clin Orthop Surg", "h": "TKA nel varo: togliere i grandi osteofiti posteriori allarga lo spazio mediale", "v": "Serie retrospettiva con misure intraoperatorie su TKA posterostabilizzata; l'effetto cresce con la dimensione dell'osteofito; nessun esito clinico.", "pmid": "42877329", "doi": "10.4055/cios26098", "temi": ["TKA", "osteofiti", "gap mediale"]}, {"dot": "gray", "j": "Front Med", "h": "Osteotomia tibiale alta: bassa massa ossea senza differenze significative a due anni", "v": "Coorte retrospettiva; gli autori scrivono che l'assenza di differenze non prova l'equivalenza e che lo studio non esclude differenze rilevanti o complicanze rare.", "pmid": "42876614", "doi": "10.3389/fmed.2026.1922205", "temi": ["HTO", "osteoporosi", "varo"]}, {"dot": "gray", "j": "Knee", "h": "Osteotomia fibulare prossimale nell'artrosi mediale: sintomi migliori, prove osservazionali", "v": "Revisione sistematica con sintesi narrativa: meccanismo di scarico mediale più che di correzione; disfunzione transitoria del peroneo frequente, lesioni permanenti documentate.", "pmid": "42880209", "doi": "10.1016/j.knee.2026.104653", "temi": ["osteotomia", "artrosi mediale", "fibula"]}, {"dot": "gray", "j": "J Knee Surg", "h": "GLP-1 prima della TKA: meno infarto e trombosi venosa nei dati TriNetX", "v": "Coorte retrospettiva appaiata su dati amministrativi USA; associazione e non causalità; l'embolia polmonare non cambia.", "pmid": "42880346", "doi": "10.1055/a-2982-7440", "temi": ["TKA", "GLP-1", "trombosi"]}, {"dot": "gray", "j": "Clin Orthop Surg", "h": "Ketorolac nel LCA pediatrico: meno oppioidi, più nuove ricostruzioni a due anni", "v": "Coorte appaiata su dati TriNetX; associazione che non prova la causalità, senza dati sull'innesto o sulla tecnica nell'abstract.", "pmid": "42877295", "doi": "10.4055/cios25488", "temi": ["LCA pediatrico", "analgesia", "rirottura"]}, {"dot": "gray", "j": "J Vasc Interv Radiol", "h": "Embolizzazione genicolare: meno infiltrazioni dopo, passaggio alla protesi invariato", "v": "Coorte su dati assicurativi USA con controlli appaiati; misura infiltrazioni e passaggio a TKA, nessun esito clinico.", "pmid": "42874703", "doi": "10.1016/j.jvir.2026.109144", "temi": ["embolizzazione genicolare", "artrosi", "infiltrazioni"]}, {"dot": "gray", "j": "Front Surg", "h": "UKA a menisco mobile o fisso: esiti brevi simili, il fisso costa meno", "v": "Retrospettiva cinese su gruppi piccoli e a breve termine; nessun dato di sopravvivenza dell'impianto.", "pmid": "42865442", "doi": "10.3389/fsurg.2026.1746302", "temi": ["UKA", "menisco mobile", "costi"]}];
var SCOPERTE=[{"t": "Intelligenza artificiale per il paziente ortopedico anziano: serve seguire tutto il percorso, non un singolo compito", "v": "Revisione dal Balgrist di Zurigo: propone di passare da modelli per singoli compiti a modelli che seguono l'intero percorso di cura, e chiede calibrazione, validazione esterna e prospettica e monitoraggio dopo l'introduzione. Vale la deviazione perché elenca i criteri con cui giudicare qualsiasi strumento di IA che ti verrà proposto; è una revisione narrativa di livello IV, senza dati nuovi.", "pmid": "42879167", "doi": "10.1002/ksa.70647", "temi": ["intelligenza artificiale", "paziente anziano", "validazione"]}, {"t": "Vietnam: un sistema che gradua l'artrosi sulla radiografia e scrive il referto con un modello linguistico", "v": "Rete profonda più Gemini, addestrata su adulti dello studio vietnamita sull'osteoporosi: gradua l'artrosi di ginocchio con la scala di Kellgren-Lawrence e genera referti strutturati. Vale la deviazione perché viene da un contesto a risorse limitate; validazione su un solo studio di popolazione, nessun esito clinico.", "pmid": "42877661", "doi": "10.1016/j.afos.2026.05.003", "temi": ["intelligenza artificiale", "radiografia", "Vietnam"]}, {"t": "Il tratto ileotibiale come cinturino biologico nella riparazione del LCA: un modello a elementi finiti", "v": "Simulazione su un solo ginocchio: con uno spessore intermedio del tratto e un tunnel intermedio le sollecitazioni sull'innesto restano basse e la lassità vicina a quella del ginocchio intatto. Vale la deviazione perché collega riparazione del LCA e rinforzo biologico; un solo modello, nessun paziente.", "pmid": "42877147", "doi": "10.3389/fbioe.2026.1913327", "temi": ["riparazione LCA", "tratto ileotibiale", "biomeccanica"]}];
var SOC={"1": {"video": "Dopo la rottura del legamento crociato anteriore, quando una calciatrice può tornare in campo? Un consensus europeo di ottobre 2026, con ventisei esperti, indica che non dipende da un numero fisso di mesi ma dal raggiungimento di alcune tappe cliniche e funzionali. La tappa centrale è il recupero della forza del muscolo davanti alla coscia; si valutano anche la risposta dei muscoli nei movimenti rapidi e la sicurezza della giocatrice, e si riprende il gioco a gradi.\n\nIl limite: sono indicazioni concordate da esperti, non il risultato di una prova su pazienti, e dall'abstract non si leggono le soglie numeriche.\nFonte: PubMed, PMID 42875873.", "linkedin": "Consensus UEFA sul LCA nel calcio femminile, parte 2 (Sci Med Footb, ottobre 2026): 26 esperti, 180 affermazioni, consenso su 170 (94%). Rientro a criteri e non a tempi fissi, con la forza del quadricipite come tappa centrale, prontezza neuromuscolare e psicologica integrate e rientro a fasi.\n\nLimiti: consenso di esperti, soglie numeriche e livelli di evidenza non nell'abstract, testo completo non aperto.\nFonte: PubMed, PMID 42875873.", "instagram": "Crociato e calcio femminile: si torna in campo per tappe.\nUn consensus di 26 esperti europei: forza della coscia, prontezza dei muscoli e della mente, rientro a gradi.\nIndicazioni concordate da esperti, non una prova su pazienti.\nFonte: PubMed, PMID 42875873.", "pazienti": "Dopo la rottura del legamento crociato, una calciatrice torna in campo quando raggiunge alcune tappe e non dopo un numero fisso di mesi. Lo indica un documento di ventisei esperti europei, pubblicato a ottobre 2026: contano la forza della coscia, la risposta dei muscoli nei movimenti rapidi e la sicurezza della giocatrice, e il ritorno avviene a gradi.\n\nSono indicazioni generali di esperti per il calcio femminile: tempi e tappe di ciascuna persona si decidono con chi segue il recupero.\nFonte: PubMed, PMID 42875873."}};
var SOCV={"1": {"video": {"chir": ["Consensus UEFA sul legamento crociato anteriore nel calcio femminile, parte due, pubblicato su Science and Medicine in Football a ottobre 2026. Un pannello di ventisei esperti ha valutato centottanta affermazioni sulla riabilitazione e sul rientro in campo, in tre round Delphi con metodo RAND-UCLA modificato: consenso su centosettanta, il novantaquattro per cento. L'indicazione principale è una progressione a criteri clinici e funzionali, non a tempi fissi.", "La forza del quadricipite è la tappa centrale. Accanto a essa il pannello integra la prontezza neuromuscolare e quella psicologica, e propone un rientro a fasi che riespone gradualmente la giocatrice alle richieste fisiche e cognitive della partita. Paura della nuova lesione, motivazione, comunicazione e rete di sostegno sono considerati fattori di recupero, non contorno.", "Il limite: è un consenso di esperti. Il novantaquattro per cento misura l'accordo del pannello, non la solidità della prova sottostante. Le soglie numeriche, per esempio quale simmetria di forza richiedere, e i livelli di evidenza non compaiono nell'abstract e il testo completo non è stato aperto. Per la pratica: la simmetria di forza resta una tappa, da affiancare a prontezza psicologica e prova neuromuscolare.\nFonte: PubMed, PMID 42875873."], "misto": ["Dopo la rottura del legamento crociato anteriore, quando una calciatrice può tornare in campo? Un consensus europeo di ottobre 2026, pubblicato su Science and Medicine in Football, risponde con ventisei esperti e centottanta affermazioni, e trova accordo su centosettanta. La risposta di fondo: non dopo un numero fisso di mesi, ma quando si superano alcune tappe cliniche e funzionali.", "Fra queste, la tappa centrale è il recupero della forza del muscolo davanti alla coscia, il quadricipite. Il gruppo chiede di valutare anche quanto i muscoli rispondono ai movimenti rapidi e quanto la giocatrice si sente pronta, e di riprendere il gioco a gradi, con allenamenti che riportano poco alla volta le richieste della partita. Contano anche la paura di infortunarsi di nuovo, la motivazione e il sostegno di chi sta intorno.", "Il limite: sono indicazioni concordate da esperti, non il risultato di una prova su pazienti, e dall'abstract non si leggono le soglie numeriche, per esempio quanta forza serva rispetto all'altra gamba. Il testo completo non è stato aperto.\nFonte: PubMed, PMID 42875873."], "pazienti": ["Dopo la rottura del legamento crociato, per una calciatrice il ritorno in campo richiede tempo e un percorso ben guidato. Un gruppo di ventisei esperti europei ha messo per iscritto come accompagnarlo, in un documento pubblicato a ottobre 2026. Il punto principale: non si torna a giocare dopo un numero fisso di mesi, ma quando si raggiungono alcune tappe.", "La prima tappa è la forza della coscia, che deve tornare vicina a quella dell'altra gamba. Poi si valuta come rispondono i muscoli nei movimenti rapidi e quanto la giocatrice si sente sicura. Il ritorno avviene a gradi: all'inizio si allena una parte del gioco, poi si aggiungono poco alla volta le situazioni della partita. Anche la paura di farsi male di nuovo conta.", "Sono indicazioni di esperti per il calcio femminile, non il risultato di un esperimento su pazienti, e i tempi e le tappe di ciascuna persona si decidono con chi segue il percorso di recupero.\nFonte: PubMed, PMID 42875873."]}, "linkedin": {"chir": ["Consensus UEFA sul LCA nel calcio femminile, parte 2 (Sci Med Footb, ottobre 2026): pannello di 26 esperti, RAND-UCLA modificato, 180 affermazioni in tre round Delphi, consenso su 170 (94%). Progressione a criteri clinici e funzionali e non a tempi fissi, con il recupero della forza del quadricipite come tappa centrale.", "Integrazione della prontezza neuromuscolare e psicologica; rientro a fasi con riesposizione graduale alle richieste fisiche e cognitive del gioco.", "Limiti: consenso di esperti (accordo, non solidità della prova), soglie numeriche e livelli di evidenza non riportati nell'abstract, testo completo non aperto.\nFonte: PubMed, PMID 42875873."], "misto": ["Dopo la rottura del crociato nel calcio femminile: un consensus UEFA (Science and Medicine in Football, ottobre 2026) con 26 esperti trova accordo su 170 affermazioni su 180. Il rientro segue tappe cliniche e funzionali e non un calendario fisso; la tappa centrale è il recupero della forza del quadricipite.", "Il pannello chiede di valutare anche la prontezza dei muscoli e quella psicologica e di riprendere il gioco a gradi.", "Limite: indicazioni concordate da esperti, non una prova su pazienti; le soglie numeriche non sono nell'abstract.\nFonte: PubMed, PMID 42875873."], "pazienti": ["Dopo la rottura del crociato, una calciatrice torna in campo quando raggiunge alcune tappe, non dopo un numero fisso di mesi. Lo indica un documento di 26 esperti europei, pubblicato a ottobre 2026.", "Fra le tappe: la forza della coscia, la risposta dei muscoli nei movimenti rapidi e la sicurezza della giocatrice. Il ritorno avviene a gradi.", "Sono indicazioni generali di esperti: tempi e tappe di ciascuna persona si decidono con chi segue il recupero.\nFonte: PubMed, PMID 42875873."]}, "instagram": {"chir": ["Consensus UEFA sul LCA nel calcio femminile, parte 2.", "26 esperti, 180 affermazioni, consenso su 170. Rientro a criteri e non a tempi fissi; forza del quadricipite come tappa centrale.", "Consenso di esperti: soglie numeriche non nell'abstract.\nFonte: PubMed, PMID 42875873."], "misto": ["Crociato e calcio femminile: si torna in campo per tappe.", "Un consensus di 26 esperti europei: forza della coscia, prontezza dei muscoli e della mente, rientro a gradi.", "Indicazioni concordate da esperti, non una prova su pazienti.\nFonte: PubMed, PMID 42875873."], "pazienti": ["Dopo il crociato si torna a giocare per tappe.", "Esperti europei indicano: forza della coscia, sicurezza nei movimenti e ritorno graduale, non un numero fisso di mesi.", "Indicazioni generali: tempi e tappe si decidono con chi segue il recupero.\nFonte: PubMed, PMID 42875873."]}, "reel": {"chir": ["Consensus UEFA sul LCA.", "Rientro a criteri, non a tempi; quadricipite al centro.", "Consenso di esperti, soglie non riportate.\nFonte: PubMed, PMID 42875873."], "misto": ["Crociato: si torna per tappe.", "Forza della coscia, prontezza, rientro a gradi.", "Parere di esperti, non prova su pazienti.\nFonte: PubMed, PMID 42875873."], "pazienti": ["Dopo il crociato.", "Si torna a giocare per tappe, non dopo un numero fisso di mesi.", "Tempi e tappe si decidono con chi segue il recupero.\nFonte: PubMed, PMID 42875873."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #LegamentoCrociato #MedicinaDelloSport", "instagram": "#ortopedia #ginocchio #legamentocrociato #lca #calciofemminile #ritornoallosport #riabilitazione #medicinadellosport #ortopediaticino #medicinabasatasulleprove", "kw": "crociato anteriore, calcio femminile, ritorno allo sport, riabilitazione, criteri di rientro"}};
var NLB={"1": {"prof": ["Consensus UEFA sul LCA nel calcio femminile: rientro a criteri, forza del quadricipite al centro", "Consensus di esperti (Sci Med Footb, ottobre 2026; RAND-UCLA modificato, 26 esperti): su 180 affermazioni il consenso è raggiunto su 170 (94%); progressione su tappe cliniche e funzionali e non su tempi fissi, con il recupero della forza del quadricipite come tappa centrale, valutazioni neuromuscolari e psicologiche integrate e rientro a fasi.", "Nota critica: è un consenso di esperti, non una misura dell'effetto; soglie numeriche e livelli di evidenza non sono nell'abstract e il testo completo non è stato aperto."], "mix": ["Dopo la rottura del crociato nel calcio femminile: si rientra quando si superano delle tappe, non dopo un numero di mesi", "Un gruppo di 26 esperti, riunito da una federazione calcistica europea, ha valutato 180 affermazioni sulla riabilitazione e sul ritorno in campo dopo la rottura del legamento crociato anteriore e ha trovato accordo su 170. Le indicazioni sono seguire tappe cliniche e funzionali, mettere al centro il recupero della forza della coscia, valutare anche la prontezza dei muscoli e della mente e riprendere il gioco a gradi.", "Nota sul limite: è l'opinione concordata di esperti, non il risultato di una prova su pazienti, e dall'abstract non si leggono le soglie numeriche."], "paz": ["Dopo la rottura del crociato: il ritorno al calcio segue tappe, non il calendario", "Un gruppo di esperti ha messo per iscritto come accompagnare le calciatrici dopo la rottura del legamento crociato: si riprende il gioco quando si raggiungono alcune tappe, fra cui il recupero della forza della coscia, e non quando è passato un certo tempo. Contano anche la fiducia nel ginocchio e la ripresa graduale degli allenamenti.", "Si tratta di indicazioni di esperti per il calcio femminile: nel singolo caso i tempi e le tappe si decidono con chi segue il percorso di recupero."], "kw": "crociato anteriore, calcio femminile, ritorno allo sport, riabilitazione"}, "2": {"prof": ["LCA in 215 calciatori professionisti: rotture dell'innesto al 5,6% a 100 mesi, rinforzo laterale senza effetto dimostrato", "Coorte retrospettiva (KSSTA, ottobre 2026; livello III): 13 rotture su 232 LCA, 12,9% senza e 4,5% con procedura laterale extra-articolare, ma HR 2,48 (IC 95% 0,49-9,87; p=0,246); lassità preoperatoria ≥7 mm (HR 2,72) e innesto rotuleo (HR 3,14) predicono il reintervento; lesione controlaterale nel 27,1%.", "Nota critica: 4 eventi su 31 contro 9 su 201, quindi confronto muto; indicazione al rinforzo non casuale, innesto non descritto nell'abstract."], "mix": ["Calciatori professionisti operati di crociato: l'innesto regge a lungo, ma un rinforzo laterale non ha dimostrato di proteggerlo", "In 215 calciatori professionisti operati di crociato, dopo in media più di otto anni il legamento ricostruito si era rotto di nuovo in 13 casi su 232. Con un rinforzo laterale le rotture sono state meno in percentuale, ma i numeri sono troppo piccoli per dire che sia stato il rinforzo a fare la differenza.", "Nota sul limite: il gruppo senza rinforzo era di soli 31 pazienti e la scelta di aggiungerlo non era casuale; la lesione dell'altro ginocchio è stata frequente, soprattutto nelle atlete."], "paz": ["Calciatori professionisti dopo il crociato: nella maggior parte dei casi il legamento nuovo ha retto", "In uno studio su 215 calciatori professionisti operati al crociato, il legamento ricostruito si è rotto di nuovo in circa un caso su diciotto in più di otto anni. Non è emerso con certezza se aggiungere un piccolo rinforzo laterale riduca ancora questo rischio.", "Sono atleti professionisti, un gruppo particolare: per ciascuno la scelta dell'intervento si decide con il chirurgo."], "kw": "crociato anteriore, calciatori, rottura dell'innesto, tenodesi laterale"}, "3": {"prof": ["LCA transfisario a meno di 2 anni dalla maturità: variazioni di allineamento minime in mediana, ma 16-28% con spostamenti rilevanti", "Studio prospettico multicentrico PLUTO (AJSM, ottobre 2026; livello 2): 91 pazienti, a un anno asse meccanico +2,9 mm in mediana, ma ≥10 mm nel 28% (73% in valgo) e variazioni angolari ≥5° nel 16-17%; un paziente (1%) con indicazione a intervenire per disturbo di crescita.", "Nota critica: un solo anno di follow-up, nessun controllo non operato, soglie convenzionali; pendenza tibiale senza valore nell'abstract."], "mix": ["Crociato nei ragazzi vicini alla fine della crescita: in media le gambe restano allineate, in alcuni casi l'asse cambia", "In 91 ragazzi operati di crociato a meno di due anni dalla fine della crescita, un anno dopo l'allineamento della gamba era cambiato poco nella maggior parte dei casi. In una quota fra il 16 e il 28% i cambiamenti erano rilevanti, più spesso verso il valgo (le ginocchia a X), e per un paziente è stato raccomandato un intervento per un disturbo di crescita.", "Nota sul limite: un anno di osservazione è breve per un disturbo di crescita e non c'è un gruppo di ragazzi non operati con cui confrontare."], "paz": ["Crociato nei ragazzi ancora in crescita: dopo l'intervento l'allineamento della gamba va controllato nel tempo", "In un gruppo di 91 ragazzi operati di crociato quando mancava poco alla fine della crescita, la forma della gamba è cambiata poco nella maggior parte dei casi. In alcuni, però, l'asse della gamba si è spostato in modo evidente, e per questo gli autori consigliano radiografie prima dell'intervento e controlli fino alla fine della crescita.", "Lo studio segue i ragazzi per un anno soltanto: i controlli successivi e le decisioni sul singolo caso si concordano con il chirurgo."], "kw": "crociato anteriore adolescenti, crescita, allineamento, ginocchio"}, "4": {"prof": ["MPFL: rientro 85-100%, ma solo 14-40% soddisfa tutti i criteri e il quadricipite spesso resta sotto il 90% di LSI", "Revisione sistematica di 6 studi, 243 pazienti (Arthrosc Sports Med Rehabil, ottobre 2026; livello IV): LSI dell'estensione isocinetica 70-96%, del salto singolo 85-93%, rientro a 6,1-8,1 mesi; criteri oggettivi espliciti definiti da una minoranza di studi.", "Nota critica: studi di livello III-IV, protocolli e soglie diversi, 41% con procedure ossee associate, nessuna stima unica né esiti di recidiva."], "mix": ["Dopo la ricostruzione del legamento della rotula: quasi tutti tornano allo sport, ma pochi superano tutti i test", "Una revisione di sei studi su 243 pazienti operati per instabilità della rotula mostra un rientro allo sport fra l'85 e il 100% a sei-otto mesi. Quando i test di forza e di salto sono definiti, però, solo il 14-40% li supera tutti, e la forza davanti alla coscia resta spesso sotto il 90% dell'altra gamba.", "Nota sul limite: gli studi sono pochi e usano test e soglie diversi; non si sa se superare i test protegga da un nuovo episodio."], "paz": ["Instabilità della rotula operata: il ritorno allo sport è frequente, ma i test di forza vanno fatti con cura", "Dopo l'intervento al legamento che tiene la rotula al suo posto, nella maggior parte degli studi la ripresa dello sport avviene dopo sei-otto mesi. I test di forza e di salto, però, non sono fatti nello stesso modo ovunque e la forza della coscia spesso non ha ancora raggiunto quella dell'altra gamba.", "I risultati dipendono dal caso singolo e dai test usati: il momento giusto per riprendere lo sport si decide con il chirurgo e il fisioterapista."], "kw": "instabilità rotulea, legamento patello-femorale mediale, ritorno allo sport, ginocchio"}, "5": {"prof": ["Consensus UEFA sul LCA nel calcio femminile: prevenzione con programmi multicomponente e alta adesione", "Consensus di esperti (Sci Med Footb, ottobre 2026; RAND-UCLA modificato, 31 esperti e una giocatrice): consenso su 88 di 101 affermazioni; i programmi con esercizi pliometrici, di forza e di controllo prossimale, 2-3 volte a settimana per 15-20 minuti, riducono le lesioni senza contatto se l'adesione è alta.", "Nota critica: raccomandazione di esperti, senza stima della riduzione del rischio nell'abstract; riferita al calcio femminile."], "mix": ["Prevenire la rottura del crociato nel calcio femminile: pochi esercizi regolari, fatti con costanza da tutta la squadra", "Un gruppo di esperti europei ha concordato su 88 affermazioni su 101 riguardo ai fattori di rischio e alla prevenzione. Indicano programmi con salti, esercizi di forza e di controllo del movimento, due-tre volte a settimana per quindici-venti minuti, che riducono le rotture senza contatto se vengono fatti con costanza.", "Nota sul limite: è un parere condiviso di esperti, non una misura di quanto il rischio scenda."], "paz": ["Crociato e calcio femminile: esercizi regolari di salto, forza e controllo aiutano a prevenire le rotture", "Secondo un gruppo di esperti, brevi sedute di esercizi, due o tre volte a settimana, con salti, forza e controllo del movimento, possono ridurre le rotture del legamento crociato che avvengono senza contatto, a patto di farle con regolarità e di inserirle negli allenamenti.", "Sono indicazioni generali per il calcio femminile: non azzerano il rischio e non sostituiscono la valutazione del singolo caso."], "kw": "prevenzione crociato, calcio femminile, allenamento neuromuscolare, ginocchio"}, "6": {"prof": ["LCA e sesso: rientro a 5 anni simile (61,2% contro 59,5%), recupero del livello pre-infortunio 45,1% contro 28,1%", "Coorte retrospettiva (KSSTA, ottobre 2026; livello III), 479 LCA primari: uomini con Tegner, IKDC e ACL-RSI più alti a 5 anni; OR del sesso maschile per il recupero del livello pre-infortunio 2,16 (IC 95% 1,40-3,39), 1,93 (IC 95% 1,20-3,15) con le variabili a 6 mesi.", "Nota critica: retrospettivo, solo pazienti con follow-up a 5 anni, innesto non descritto nell'abstract, denominatori non espliciti."], "mix": ["Crociato operato: uomini e donne rientrano allo sport in egual misura, ma non ritrovano allo stesso modo il livello di prima", "Su 479 operati di crociato seguiti per cinque anni, la quota di chi ha ripreso lo sport è simile fra uomini e donne. Il livello di attività che avevano prima dell'infortunio è stato ritrovato dal 45,1% degli uomini e dal 28,1% delle donne, che a cinque anni hanno anche punteggi di funzione e di fiducia nel ginocchio un po' più bassi.", "Nota sul limite: lo studio è retrospettivo e include solo chi è stato seguito per cinque anni; il sesso può rappresentare differenze di sport, aspettative e riabilitazione."], "paz": ["Dopo l'intervento al crociato, tornare allo sport non vuol dire sempre ritrovare il livello di prima", "In uno studio su quasi cinquecento persone operate al legamento crociato, uomini e donne hanno ripreso lo sport in misura simile dopo cinque anni. Le donne, però, hanno ritrovato meno spesso lo stesso livello di attività che avevano prima dell'infortunio e hanno riferito un po' meno fiducia nel ginocchio.", "È un risultato medio di un solo centro: non dice che cosa accadrà a una persona in particolare, e le aspettative si discutono con il chirurgo."], "kw": "crociato anteriore, differenze di sesso, ritorno allo sport, risultati a cinque anni"}, "7": {"prof": ["NMES dopo LCA: forza isometrica più alta a 6-12 settimane in una metanalisi di 21 RCT, nessun dato oltre le 12", "Metanalisi (Arthroscopy, ottobre 2026; livello I), 687 pazienti: forza isometrica assoluta con differenza 0,24 (IC 95% 0,2-0,27) a 6-12 settimane; in percentuale dell'arto sano DMS 0,87 (IC 95% 0,11-1,64; eterogeneità 87%); Lysholm più alto (p=0,02), IKDC e forza isocinetica invariati.", "Nota critica: pool di 109 e 264 pazienti, eterogeneità elevata, nessuna evidenza oltre le 12 settimane né sul rientro."], "mix": ["Stimolazione elettrica dei muscoli dopo il crociato: la forza della coscia risale prima, ma solo nei primi mesi", "Una metanalisi di 21 studi randomizzati (687 pazienti) indica che la stimolazione elettrica dei muscoli, aggiunta alla fisioterapia, fa recuperare più in fretta la forza della coscia fra la sesta e la dodicesima settimana. Dopo i tre mesi non si vede una differenza, e la funzione del ginocchio migliora solo in alcuni punteggi.", "Nota sul limite: la stima dell'effetto è molto incerta per la differenza fra gli studi e non dimostra un rientro più sicuro."], "paz": ["Dopo l'intervento al crociato, la stimolazione elettrica dei muscoli può far recuperare prima la forza", "Raccolti ventuno studi, la stimolazione elettrica della coscia usata insieme alla fisioterapia ha aiutato a recuperare un po' prima la forza nei primi mesi dopo l'operazione. Dopo i tre mesi non è emersa una differenza chiara.", "L'utilità per la singola persona dipende dal caso e dal programma di riabilitazione, che si concordano con chi segue il recupero."], "kw": "crociato anteriore, riabilitazione, stimolazione elettrica, forza del quadricipite"}, "8": {"prof": ["Menisco laterale ipermobile: nota tecnica di Bologna con manovra clinica e sutura all-inside sequenziale", "Nota tecnica (Arthrosc Tech, ottobre 2026): manovra di flessione, valgo e rotazione esterna per sospettare l'instabilità del corno posteriore, e stabilizzazione con suture verticali all-inside dallo iato popliteo al capsulare posteriore, con prove di sonda e aspirazione per evitare il sovravincolo e stimolazione midollare nella notch.", "Nota critica: nessun paziente né esito nell'abstract; non è una prova di efficacia."], "mix": ["Menisco laterale che si muove troppo: una tecnica per fissarlo con piccole suture dall'interno dell'articolazione", "Il menisco laterale ipermobile è una causa poco comune di dolore dietro e di lato al ginocchio e spesso non si vede con gli esami per immagini. Un gruppo di Bologna descrive un gesto clinico per sospettarlo e una tecnica artroscopica che lo fissa con suture in sequenza, mantenendo la sua mobilità fisiologica.", "Nota sul limite: è la descrizione di una tecnica, senza pazienti né risultati nell'abstract."], "paz": ["Dolore dietro e di lato al ginocchio: una possibile causa è un menisco troppo mobile, che si può fissare in artroscopia", "A volte il dolore laterale e posteriore del ginocchio dipende da un menisco che si muove più del normale e che le immagini non mostrano. Un gruppo di chirurghi ha descritto come riconoscerlo con una manovra e come fissarlo in artroscopia, mantenendone il movimento naturale.", "È la descrizione di una tecnica, non uno studio sui risultati: se ne parla con il chirurgo nel singolo caso."], "kw": "menisco laterale, instabilità meniscale, artroscopia, dolore laterale del ginocchio"}, "9": {"prof": ["Conversione robotica di UKA in TKA: aumenti nel 13,6%, steli nel 3,6%, sopravvivenza 93,2-100% a 3,6 anni", "Revisione sistematica (J Robot Surg, ottobre 2026; livello IV), 5 studi e 136 pazienti con MAKO o ROSA, follow-up medio 20,9 mesi: flessione 119-130°, complicanze 0-11% fra gli studi, una frattura tibiale intraoperatoria (0,7%).", "Nota critica: serie piccole senza confronto con la conversione manuale, follow-up breve, eventi rari non stimabili."], "mix": ["Da protesi monocompartimentale a totale con il robot: servono pochi rinforzi, ma i dati sono ancora brevi", "Una revisione di cinque piccoli studi su 136 pazienti, in cui una protesi monocompartimentale è stata sostituita da una totale con l'aiuto del robot, mostra che di rado servono rinforzi o steli (13,6% e 3,6%), con buona mobilità e impianti ancora in sede in oltre il 93% dei casi fino a circa tre anni e mezzo.", "Nota sul limite: manca un confronto con la conversione fatta senza robot e il controllo è ancora breve."], "paz": ["Sostituire una protesi parziale con una totale usando il robot: i primi dati sono favorevoli ma brevi", "Alcuni piccoli studi su 136 persone mostrano che, quando una protesi parziale del ginocchio deve essere sostituita da una totale con l'aiuto del robot, spesso bastano pochi elementi aggiuntivi e il movimento del ginocchio è buono. Il controllo è però breve, circa due anni.", "Non c'è un confronto con la stessa operazione senza robot: la scelta si discute con il chirurgo."], "kw": "protesi monocompartimentale, protesi totale di ginocchio, revisione, chirurgia robotica"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"red",sec:"res",j:"Sci Med Footb",h:"Consensus UEFA sul LCA nel calcio femminile (parte 2): rientro a criteri, con la forza del quadricipite come tappa centrale",v:"Consensus di esperti (RAND-UCLA modificato, tre round Delphi): un pannello multidisciplinare di 26 esperti valuta 180 affermazioni sulla riabilitazione, sul rientro in campo e sulla prospettiva delle giocatrici dopo una lesione del LCA; il consenso è raggiunto su 170 (94%). Il pannello sostiene una progressione a criteri, su tappe cliniche e funzionali e non su tempi fissi; mette il recupero della forza del quadricipite come tappa centrale, affianca la prontezza neuromuscolare e psicologica e propone un rientro a fasi, che riespone gradualmente la giocatrice alle richieste fisiche e cognitive della partita.",ax:"Verhagen, Arundale, Bahtijarevic, Brogden, Chaput … Della Villa … Okholm Kryger (30 autori)",date:"ott 2026",meta:"consensus Delphi (RAND-UCLA modificato), 26 esperti, 180 affermazioni in tre round · [consenso di esperti]",pmid:'42875873',doi:'10.1080/24733938.2026.2726165',journal:"Science & medicine in football",authors:"Verhagen E, Arundale AJH, Bahtijarevic Z, Brogden C, Chaput M, Conner-Rilk S, Datson N, Della Villa F, Ezzat A, Ferrer E, et al. (30 autori; ultima: Okholm Kryger K)",design:"Consensus di esperti con metodo RAND-UCLA Appropriateness modificato: 180 affermazioni valutate e riviste in tre round Delphi da un pannello multidisciplinare di 26 esperti (medicina dello sport, fisioterapia, ortopedia, scienza della prestazione). È la parte 2 di una serie UEFA; la parte 1 (prevenzione) è la scheda 5. Letto l'abstract su PubMed; testo completo non in PMC e non aperto. Dall'abstract non risultano né la revisione di letteratura che ha sostenuto le affermazioni né i livelli di evidenza delle singole affermazioni.",pop:"Pannello di 26 esperti in medicina dello sport, fisioterapia, ortopedia e scienza della prestazione. Nessun paziente arruolato: è un consenso, non uno studio clinico. Fra gli autori compare Francesco Della Villa (Isokinetic), della tua rete.",results:"180 affermazioni valutate in tre round; consenso su 170 (94%). Indicazioni principali: progressione a criteri e non a tempi fissi; recupero della forza del quadricipite come tappa centrale; valutazioni di prontezza neuromuscolare e psicologica integrate; rientro a fasi con riesposizione graduale alle richieste fisiche e cognitive del gioco; paura della nuova lesione, motivazione, comunicazione e rete di sostegno riconosciute come fattori di recupero. Soglie numeriche (per esempio una simmetria di forza minima) e livelli di evidenza delle affermazioni: non riportati nell'abstract. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: un approccio centrato sulla giocatrice, a criteri e a fasi, con la forza del quadricipite come tappa centrale e i fattori psicologici e sociali come parte della cura.",limits:"Consenso di esperti: il 94% di accordo misura quanto il pannello concorda, non quanto sia solida la prova sottostante · riguarda il calcio femminile, non è estendibile senza cautela a ogni sport o livello · soglie numeriche e livelli di evidenza non nell'abstract, testo completo non aperto (NON VERIFICATO oltre l'abstract) · pannello convocato nel contesto UEFA: nessun conflitto dichiarato nell'abstract, non verificato.",perte:"Scheda rossa per regola (consensus sul LCA), non per un conflitto con la tua pratica. Tocca la tensione 4 (criterio di rientro): il consensus abbandona i tempi fissi e tiene la forza del quadricipite al centro, quindi conferma la tua LSI, ma la mette accanto a prontezza psicologica e neuromuscolare e a un rientro a fasi, non come cancello unico. Cosa fare: nel tuo criterio di rientro annota con la LSI anche la prontezza psicologica (ACL-RSI) e una prova neuromuscolare o di atterraggio; la soglia numerica va cercata nel testo completo, che non ho aperto."},
{n:2,mono:"m-kssta",dot:"green",sec:"res",j:"KSSTA",h:"LCA nei calciatori professionisti: innesti che reggono a lungo, ma il rinforzo laterale non dimostra un effetto protettivo",v:"Coorte retrospettiva del gruppo SANTI (Lione; livello III): 232 LCA primari in 215 calciatori professionisti, 31 isolati e 201 con procedura laterale extra-articolare (LEAP). A 100 mesi di follow-up medio 13 rotture dell'innesto (5,6%): 12,9% senza LEAP contro 4,5% con LEAP, ma nell'analisi del tempo all'evento la differenza non è significativa (HR 2,48; IC 95% 0,49-9,87; p=0,246). Lassità preoperatoria ≥7 mm (HR 2,72) e innesto rotuleo (HR 3,14) sono fattori di rischio indipendenti di reintervento; lesione del LCA controlaterale nel 27,1% dei ginocchi, più nelle atlete (48,7% contro 22,8%).",ax:"Santamaria, Santos, Ayata, Wehbe, Sonnery-Cottet V., Campos, Corti, Vieira, Sonnery-Cottet B.",date:"ott 2026",meta:"coorte retrospettiva, 232 LCA in 215 calciatori professionisti (31 isolati, 201 con LEAP), follow-up medio 100 mesi · [livello III]",pmid:'42879166',doi:'10.1002/ksa.70641',journal:"Knee surgery, sports traumatology, arthroscopy",authors:"Santamaria F, Santos PM, Ayata M, Wehbe H, Sonnery-Cottet V, Campos JP, Corti J, Vieira TD, Sonnery-Cottet B",design:"Coorte retrospettiva (Ramsay Santé, Hôpital privé Jean Mermoz, Centre Orthopédique Santy, Lione; FIFA Medical Center of Excellence), livello III dichiarato. Endpoint primario la rottura dell'innesto (sintomatica, confermata clinicamente e con imaging, oppure revisione chirurgica); analisi del tempo all'evento con follow-up variabile; Cox multivariata per i predittori. Lesione controlaterale registrata solo in modo descrittivo. Letto l'abstract; testo completo non aperto.",pop:"232 LCA primari in 215 calciatori professionisti: 31 LCA isolati e 201 LCA con LEAP. Follow-up medio 100 mesi. Tipo di innesto per gruppo, età e quota di donne: non riportati nell'abstract (l'abstract nomina l'innesto rotuleo come fattore di rischio, non dà la distribuzione).",results:"Rotture dell'innesto 13 su 232 (5,6%). Senza LEAP 12,9% (4/31), con LEAP 4,5% (9/201); HR 2,48 (IC 95% 0,49-9,87; p=0,246), senza che l'abstract dica quale gruppo sia il riferimento. Reinterventi 32 ginocchia (17,7%): 30,0% senza LEAP contro 15,2% con LEAP (p=0,0528). Lassità preoperatoria ≥7 mm: HR 2,72 (IC 95% 1,23-6,17; p=0,014); innesto rotuleo: HR 3,14 (IC 95% 1,26-7,20; p=0,037). Lesione controlaterale 27,1% (atlete 48,7% contro atleti 22,8%); fra chi ha rotto l'innesto, 53,8% anche controlaterale.",concl:"Gli autori: sopravvivenza dell'innesto durevole nei professionisti; il LEAP si associa a meno rotture ma un effetto protettivo indipendente non è confermato; l'alto tasso di lesione controlaterale indica un rischio multifattoriale.",limits:"Retrospettivo, 31 contro 201: il gruppo senza LEAP è piccolo e la scelta del LEAP non è casuale (confondimento per indicazione) · 4 eventi contro 9: confronto muto, il rischio relativo non esclude né nessun effetto né un rischio fino a circa nove volte maggiore senza LEAP · innesto e tecnica del LEAP non descritti nell'abstract · popolazione di soli professionisti, non il tuo paziente medio · una sola serie di un gruppo che pratica il LEAP.",perte:"Tocca la tensione 1 (LET su innesto rigido). Il LEAP qui è quasi la regola (201 su 232, 87%) come nella tua indicazione, ma lo studio non può dire se protegga: l'IC include l'assenza di effetto. Il gruppo di Sonnery-Cottet è nella tua rete. Cosa fare: nulla da cambiare; è un dato a lungo termine sulla sopravvivenza dell'innesto, non sposta la tensione. L'innesto non è descritto, quindi non vale per il quadricipite."},
{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Am J Sports Med",h:"LCA transfisario vicino alla maturità: allineamento quasi invariato in media, ma in una parte dei ragazzi cambia in modo rilevante",v:"Studio prospettico multicentrico PLUTO (livello 2): 91 pazienti (48 maschi), età scheletrica mediana 14,0 anni, ≤2 anni di crescita residua, LCA transfisario con tendini autologhi (hamstring 46%, quadricipite 54%) e fissazione metafisaria. A un anno le variazioni mediane dell'asse meccanico (2,9 mm), dell'angolo femorale (-1°), di quello tibiale (0°) e della dismetria (0,1 cm) sono piccole; ma il 28% ha uno spostamento dell'asse ≥10 mm (73% in valgo) e il 16-17% una variazione angolare ≥5°. Un paziente (1%) con indicazione a intervenire per disturbo di crescita.",ax:"Bram, Saville, Whalen, Farah, Sugimoto, Green … Kocher, Fabricant (27 autori)",date:"ott 2026",meta:"coorte prospettica multicentrica, 91 pazienti con ≤2 anni di crescita residua, radiografie a un anno · [livello 2]",pmid:'42877964',doi:'10.1177/03635465261492231',journal:"The American journal of sports medicine",authors:"Bram JT, Saville GH, Whalen MM, Farah S, Sugimoto D, Green DW, et al. (28 voci; ultimo: Fabricant PD)",design:"Studio prospettico multicentrico (PLUTO Study Group; indagine eseguita all'Hospital for Special Surgery), livello 2 dichiarato, su LCA primario transfisario con tendine autologo molle e fissazione metafisaria. Per ogni parametro (asse meccanico, angolo femorale distale, angolo tibiale prossimale, pendenza tibiale, dismetria) si calcola la variazione della differenza fra arto operato e sano dal preoperatorio a un anno, per scontare la crescita naturale. Letto l'abstract; testo completo non aperto.",pop:"91 pazienti (48 maschi), età scheletrica mediana 14,0 anni, ≤2 anni di crescita residua. Innesto hamstring 46% e quadricipite 54%. Perdite al follow-up, quota di LET e lesioni associate: non riportate nell'abstract.",results:"Variazioni mediane a un anno: asse meccanico 2,9 mm, angolo femorale distale -1°, angolo tibiale prossimale 0°, dismetria 0,1 cm (intervalli interquartili non riportati nell'abstract). Variazione dell'asse ≥10 mm in 28% (73% in valgo); angolo femorale ≥5° in 17% (73% in valgo); angolo tibiale ≥5° in 16% (43% in varo). Un paziente (1%; IC 95% di Wilson 0,2-6,0%, calcolo mio) con indicazione a intervenire per disturbo di crescita. Pendenza tibiale: valore non riportato nell'abstract.",concl:"Gli autori: variazioni minime a livello di coorte, ma un sottogruppo rilevante (16-28%) mostra variazioni cliniche, soprattutto verso il valgo e con riduzione della pendenza; servono valutazione radiografica preoperatoria di routine e sorveglianza fino alla maturità scheletrica.",limits:"Un solo anno di follow-up: i disturbi di crescita possono emergere dopo · nessun gruppo di controllo non operato e nessun confronto fra hamstring e quadricipite nell'abstract · la soglia che rende una variazione «clinicamente rilevante» (10 mm, 5°) è convenzionale · una rara complicanza (1 su 91) non è stimabile con precisione · pendenza tibiale citata nelle conclusioni ma senza valore in abstract.",perte:"LCA nell'adolescente è un tuo filone, e nel gruppo il quadricipite è il 54%. Cosa fare: per i ragazzi vicini alla maturità prevedi una radiografia dell'arto intero prima dell'intervento e un controllo fino alla maturità scheletrica, come indicano gli autori; il dato non dice che l'innesto transfisario sia da evitare, dice che il cambiamento di allineamento va guardato."},
{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Arthrosc Sports Med Rehabil",h:"MPFL: rientro riportato quasi sempre, ma pochi pazienti soddisfano tutti i criteri e il quadricipite resta spesso sotto il 90%",v:"Revisione sistematica (Mayo Clinic; livello IV) di 6 studi, 243 pazienti (64% donne, età media 19,4 anni) dopo ricostruzione primaria del MPFL: i test oggettivi del rientro sono eterogenei (isocinetico, salti, Y-balance); LSI 70-96% per l'estensione, 85-93% per il salto singolo; rientro 85-100% a 6,1-8,1 mesi, ma solo il 14-40% soddisfa tutti i criteri quando sono definiti. Il quadricipite resta spesso sotto il 90% di LSI al rientro.",ax:"Kang, Ward, Hevesi, Okoroha, Saris, Camp, Krych, Tagliero",date:"ott 2026",meta:"revisione sistematica di 6 studi di livello III-IV, 243 pazienti dopo ricostruzione del MPFL · [livello IV]",pmid:'42876992',doi:'10.1002/ars2.70110',journal:"Arthroscopy, sports medicine, and rehabilitation",authors:"Kang L, Ward GH, Hevesi M, Okoroha KR, Saris DBF, Camp CL, Krych AJ, Tagliero AJ",design:"Revisione sistematica (Mayo Clinic, Rochester) su Scopus, PubMed, CINAHL ed Embase, 2000-2024, di studi sul rientro allo sport e sull'indice di simmetria degli arti (LSI) dopo ricostruzione primaria del MPFL per instabilità rotulea; incluse metriche oggettive come forza isocinetica e salti. Livello IV dichiarato (studi di livello III-IV). Nessuna sintesi quantitativa nell'abstract. Testo completo disponibile su PMC (PMC13662563), non aperto.",pop:"6 studi, 243 pazienti: 64% donne, età media 19,4 anni; 41% con procedure ossee associate (osteotomia della tuberosità tibiale o trocleoplastica). Test a 6-8 mesi dall'intervento.",results:"LSI: flessione isocinetica 83-94%; estensione isocinetica 70-96%; salto singolo 85-93%; triplo salto 90-97%. Tempo al rientro 6,1-8,1 mesi; rientro 85-100%; ma solo 14-40% dei pazienti soddisfa tutti i criteri specifici dello studio, quando riportati. Stime puntuali con intervalli di confidenza: non riportate nell'abstract (sono intervalli di valori fra gli studi, non intervalli di confidenza).",concl:"Gli autori: pochi studi sul MPFL includono LSI e solo una minoranza definisce criteri oggettivi espliciti; fra quelli che li riportano, il quadricipite era spesso sotto il 90% di LSI al rientro; la variabilità di valutazione è sostanziale.",limits:"Solo 6 studi di livello III-IV, protocolli e soglie diversi: nessuna stima unica · 41% con procedure ossee associate, che mescolano gli effetti · test a 6-8 mesi, non esiti a lungo termine né reinstabilità · lo studio non dice se i criteri oggettivi proteggano dalla recidiva.",perte:"MPFL è un tuo tema prioritario e questa è la stessa domanda della tensione 4, su un altro legamento. Cosa fare: se dopo il MPFL usi una soglia di simmetria per il rientro, annota il test (strumento, posizione, tipo di contrazione): nella letteratura raccolta il quadricipite arriva spesso al rientro sotto il 90%, con rientro dichiarato quasi per tutti."},
{n:5,mono:"m-gray",dot:"gray",sec:"res",j:"Sci Med Footb",h:"Consensus UEFA sul LCA nel calcio femminile (parte 1): programmi di prevenzione multicomponente, efficaci se l'adesione è alta",v:"Consensus di esperti (RAND-UCLA modificato, tre round Delphi): 31 fra medici, scienziati dello sport, fisioterapisti e una giocatrice valutano 101 affermazioni sui fattori di rischio e sulla prevenzione delle lesioni del LCA nel calcio femminile; consenso su 88. I programmi multicomponente (esercizi pliometrici, di forza e di controllo prossimale, 2-3 volte a settimana per 15-20 minuti) sono indicati come i più efficaci per ridurre le lesioni senza contatto, purché l'adesione sia alta.",ax:"Okholm Kryger, Arundale, Bahtijarevic, Brogden, Chaput … Verhagen (29 autori)",date:"ott 2026",meta:"consensus Delphi (RAND-UCLA modificato), 31 esperti, 101 affermazioni in tre round · [consenso di esperti]",pmid:'42875874',doi:'10.1080/24733938.2026.2747391',journal:"Science & medicine in football",authors:"Okholm Kryger K, Arundale AJH, Bahtijarevic Z, Brogden C, Chaput M, Conner-Rilk S, Datson N, Ezzat A, Ferrer E, Ferrer-Roca V, et al. (29 autori; ultimo: Verhagen E)",design:"Consensus di esperti convocato da UEFA (Nyon): 31 fra medici, scienziati dello sport, fisioterapisti e una giocatrice; 101 affermazioni sintetizzate dalla letteratura e votate in modo confidenziale in tre round Delphi con metodo RAND-UCLA modificato. Parte 1 della serie (la parte 2 è la scheda 1). Letto l'abstract; testo completo non aperto.",pop:"Pannello di 31 persone (medici, scienziati dello sport, fisioterapisti, una giocatrice). Nessun paziente arruolato.",results:"101 affermazioni; consenso su 88 (87%, calcolo mio: 88/101). Conclusioni: le lesioni del LCA nel calcio femminile avvengono tipicamente senza contatto, in gesti ad alta intensità (cambi di direzione, pressing, atterraggi); fra i fattori modificabili figurano deficit di controllo neuromuscolare, di forza e di qualità del movimento; i programmi multicomponente con esercizi pliometrici, di forza e di controllo prossimale, 2-3 volte a settimana per 15-20 minuti, riducono le lesioni senza contatto quando l'adesione è alta. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: la prevenzione richiede programmi multicomponente adattati al contesto, inseriti negli allenamenti e sostenuti da coinvolgimento di allenatori e giocatrici e da supporto organizzativo.",limits:"Consenso di esperti: sostiene la raccomandazione, non misura l'effetto · nessuna stima di riduzione del rischio nell'abstract · riferito al calcio femminile · testo completo non aperto.",perte:"È prevenzione primaria, fuori dalla tua chirurgia: contesto per quando un'atleta o un allenatore chiede come ridurre il rischio. Cosa fare: nulla; se serve, il consensus indica programmi multicomponente di 15-20 minuti, 2-3 volte a settimana, con adesione alta."},
{n:6,mono:"m-kssta",dot:"gray",sec:"res",j:"KSSTA",h:"LCA e sesso: stesso tasso di rientro a 5 anni, ma le donne ritrovano meno spesso il livello di attività pre-infortunio",v:"Coorte retrospettiva (Bordeaux-Mérignac; livello III): 479 operati di LCA primario 2017-2019 (173 donne, 306 uomini) con valutazione a 6 mesi e a 5 anni. Rientro allo sport simile (uomini 61,2%, donne 59,5%; p=0,85), ma recupero del livello di attività pre-infortunio 45,1% contro 28,1% (p<0,001). Il sesso maschile è associato in modo indipendente al recupero (OR 2,16; IC 95% 1,40-3,39; p<0,001); l'associazione resta con le variabili a 6 mesi (OR 1,93; IC 95% 1,20-3,15).",ax:"Marty-Diloy, Graveleau, Bouguennec",date:"ott 2026",meta:"coorte retrospettiva, 479 LCA primari (173 donne, 306 uomini), follow-up a 5 anni · [livello III]",pmid:'42879163',doi:'10.1002/ksa.70651',journal:"Knee surgery, sports traumatology, arthroscopy",authors:"Marty-Diloy T, Graveleau N, Bouguennec N",design:"Coorte retrospettiva monocentrica (Clinique du Sport Bordeaux-Mérignac), livello III, di pazienti consecutivi con LCA primario fra gennaio 2017 e dicembre 2019, con valutazione funzionale e psicologica standardizzata a 6 mesi e follow-up disponibile a 5 anni. Endpoint primario il recupero del livello di attività pre-infortunio (Tegner postoperatorio ≥ preoperatorio); regressione logistica multivariata. Letto l'abstract; testo completo non aperto.",pop:"479 pazienti: 173 donne (36,1%) e 306 uomini (63,9%). Inclusi solo i pazienti con follow-up a 5 anni disponibile; perdite al follow-up e tipo di innesto: non riportati nell'abstract.",results:"A 6 mesi: uomini con simmetria del quadricipite più alta e deficit nei salti più bassi, ACL-RSI senza differenza. A 5 anni: rientro 187 uomini (61,2%) contro 103 donne (59,5%), p=0,85; Tegner 6 (5-7) contro 5 (4-7), p<0,001; IKDC 82,5 (75,7-87,3) contro 79,5 (72,8-86,3), p=0,02; ACL-RSI 77,5 contro 69,2, p=0,02; recupero del livello pre-infortunio 137 (45,1%) contro 48 (28,1%), p<0,001. OR del sesso maschile 2,16 (IC 95% 1,40-3,39); con le variabili a 6 mesi 1,93 (IC 95% 1,20-3,15; p=0,007); anche un minor deficit nel salto singolo è indipendente.",concl:"Gli autori: uomini e donne non hanno lo stesso profilo di recupero; le differenze iniziali sono funzionali, quelle a 5 anni riguardano livello di attività, funzione soggettiva e prontezza psicologica, pur con tassi di rientro simili; il rientro allo sport non equivale a una qualità di recupero uguale.",limits:"Retrospettivo, monocentrico, con soli pazienti che hanno un follow-up a 5 anni: possibile bias di selezione · i denominatori delle percentuali non sono espliciti (187/306 darebbe 61,1% e 137/306 44,8%): alcuni dati mancano · innesto, LET e lesioni associate non descritti nell'abstract · associazione, non causa: il sesso può coprire differenze di sport, aspettative e riabilitazione.",perte:"Contesto per la tensione 4: un «rientrato» non dice quanto vale il recupero, e il sesso modifica la probabilità di ritrovare il livello precedente. Cosa fare: nulla da cambiare; nel colloquio sulle aspettative a 5 anni, per le atlete, il livello precedente è meno probabile del solo rientro."},
{n:7,mono:"m-arth",dot:"gray",sec:"res",j:"Arthroscopy",h:"Stimolazione elettrica neuromuscolare dopo il LCA: forza isometrica più alta nelle prime settimane, nulla da dire oltre i tre mesi",v:"Metanalisi di 21 RCT (Toronto; livello I): 687 adulti (314 controlli, 373 con NMES) dopo chirurgia del LCA. Forza isometrica di estensione assoluta: differenza 0,24 (IC 95% 0,2-0,27; 109 pazienti; eterogeneità 9%) a 6-12 settimane, non oltre le 12; in percentuale dell'arto sano differenza media standardizzata 0,87 (IC 95% 0,11-1,64; 264 pazienti; eterogeneità 87%). Lysholm più alto (p=0,02), IKDC no; la forza isocinetica (4 studi) non cambia.",ax:"Daud, Lameire, Schemitsch, Whelan, Dwyer, Theodoropoulos, Chahal",date:"ott 2026",meta:"metanalisi di 21 RCT, 687 pazienti dopo chirurgia del LCA · [livello I]",pmid:'42876225',doi:'10.1002/arj.70614',journal:"Arthroscopy",authors:"Daud A, Lameire DL, Schemitsch GW, Whelan DB, Dwyer T, Theodoropoulos J, Chahal J",design:"Revisione sistematica e metanalisi di RCT (PubMed, Ovid MEDLINE, Embase fino a febbraio 2025) su adulti operati di LCA con NMES come intervento e riabilitazione standard come controllo; selezione, estrazione e rischio di bias (Cochrane) da due revisori in modo indipendente; analisi con RevMan. Livello I dichiarato. Testo completo non aperto.",pop:"21 RCT, 687 pazienti (314 controlli, 373 NMES), età media ponderata 27,0 anni, follow-up medio 18,4 settimane (4-54). Tipo di innesto e intervento associato: non riportati nell'abstract. «LCA e riparazione» nel titolo: non separati nell'abstract.",results:"Forza isometrica assoluta a 6-12 settimane: differenza 0,24 (IC 95% 0,2-0,27; p<0,01; 54 NMES contro 55 controlli, eterogeneità 9%); unità di misura non riportata nell'abstract. Forza in percentuale dell'arto non operato: DMS 0,87 (IC 95% 0,11-1,64; p=0,03; 131 contro 133; eterogeneità 87%). Dopo 12 settimane nessuna differenza. Flessione del ginocchio p=0,01, circonferenza della coscia p=0,04, Lysholm p=0,02, IKDC non significativo. Forza isocinetica (4 studi): nessuna differenza significativa.",concl:"Gli autori: la NMES come aggiunta alla fisioterapia sembra migliorare modestamente e più in fretta la forza isometrica; nessuna conclusione sul recupero funzionale o sulla forza oltre i tre mesi.",limits:"Pochi pazienti nei pool (109 e 264 su 687) e non tutti gli studi misurano la stessa cosa · eterogeneità 87% sulla forza percentuale: la stima di 0,87 è molto incerta (IC fino a 0,11) · effetto precoce su una misura isometrica, non sul rientro né sulle rotture · l'abstract non dice qualità né rischio di bias degli studi inclusi.",perte:"Tocca la tensione 4 per la parte forza: un mezzo per recuperare prima il quadricipite, non un criterio di rientro. Cosa fare: nulla da cambiare; se la forza del quadricipite è il tuo cancello, la NMES può essere un'aggiunta nelle prime 6-12 settimane, con un beneficio che oltre i tre mesi non è dimostrato."},
{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Arthrosc Tech",h:"Menisco laterale ipermobile: nota tecnica di Bologna con manovra clinica e sutura all-inside sequenziale",v:"Nota tecnica (Bologna): per il menisco laterale ipermobile, causa poco comune di dolore posterolaterale e sintomi meccanici che sfugge spesso all'imaging, gli autori descrivono una manovra clinica (flessione, valgo e rotazione esterna) e una stabilizzazione artroscopica con suture verticali all-inside in sequenza, dallo iato popliteo al capsulare posteriore e poi in senso posteriore e mediale, con prove di sonda e aspirazione per evitare il sovravincolo e stimolazione midollare nella notch.",ax:"Grassi, Cerasoli, Rinaldi, Marcheggiani Muccioli, Rossi, Zaffagnini",date:"ott 2026",meta:"nota tecnica, nessun paziente riportato nell'abstract · [livello V]",pmid:'42877523',doi:'10.1002/atn2.70338',journal:"Arthroscopy techniques",authors:"Grassi A, Cerasoli T, Rinaldi VG, Marcheggiani Muccioli GM, Rossi C, Zaffagnini S",design:"Nota tecnica (Dipartimento di Scienze Biomediche e Neuromotorie, Università di Bologna) con descrizione di una manovra clinica di provocazione e di una tecnica di stabilizzazione. Nessun disegno di studio: non ci sono pazienti né esiti nell'abstract. Testo completo disponibile su PMC (PMC13662567), non aperto.",pop:"Nessun paziente riportato nell'abstract.",results:"Nessun esito riportato. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: una strategia riproducibile e che conserva il tessuto, che ripristina la stabilità mantenendo la biomeccanica nativa del menisco.",limits:"Nota tecnica: nessun dato clinico, nessun confronto, nessun follow-up · la manovra clinica è proposta come ausilio al sospetto, non validata nell'abstract · testo completo non aperto.",perte:"Tre autori (Grassi, Marcheggiani Muccioli, Zaffagnini) sono della tua rete. Un editoriale di Arthroscopy dell'11 ottobre (PMID 42859895) ripete il messaggio: se il menisco laterale è ipermobile, ripararlo ed evitare il sovravincolo; è un parere, non una prova. Cosa fare: nulla di nuovo; la manovra può servire nel sospetto di un menisco laterale posteriore instabile con RM negativa."},
{n:9,mono:"m-jrs",dot:"gray",sec:"res",j:"J Robot Surg",h:"Conversione di UKA in TKA con il robot: pochi aumenti e buoni esiti precoci, su cinque piccole serie",v:"Revisione sistematica (HSS, New York; livello IV): 5 studi, 136 pazienti (140 ginocchia), conversione di protesi monocompartimentale in totale con robot (MAKO 105 ginocchia, ROSA 35), follow-up medio 20,9 mesi. Nessuna conversione a tecnica manuale; aumenti nel 13,6%, steli nel 3,6%; flessione 119-130°; complicanze 0-11% (una frattura tibiale intraoperatoria, 0,7%); sopravvivenza dell'impianto 93,2-100% fino a 3,6 anni.",ax:"Burgio, Persaud, Bosco, Vachhani, Zepeda, Mayman, Vigdorchik, Debbi",date:"ott 2026",meta:"revisione sistematica di 5 studi, 136 pazienti (140 ginocchia), conversione robotica UKA-TKA · [livello IV]",pmid:'42878925',doi:'10.1007/s11701-026-04063-4',journal:"Journal of robotic surgery",authors:"Burgio C, Persaud SG, Bosco F, Vachhani S, Zepeda KE, Mayman DJ, Vigdorchik JM, Debbi EM",design:"Revisione sistematica PRISMA, registrata in PROSPERO (CRD42025643211), con ricerca su PubMed, Embase e Scopus fino a ottobre 2025 di studi su UKA convertite in TKA con assistenza robotica; rischio di bias con ROBINS-I; due revisori in modo indipendente. Livello IV dichiarato. Nessuna metanalisi nell'abstract. Testo completo non aperto.",pop:"5 studi, 136 pazienti (140 ginocchia): 105 con MAKO e 35 con ROSA. Follow-up medio 20,9 mesi. Età, BMI e causa del fallimento della UKA: non riportati nell'abstract.",results:"Aumenti 13,6%, steli 3,6%; flessione 119-130° con estensione completa. Complicanze 0-11% fra gli studi: una frattura tibiale intraoperatoria (0,7%), due infezioni periprotesiche, tre rigidità, un allentamento asettico. Sopravvivenza dell'impianto 93,2-100% fino a 3,6 anni. Miglioramento di r-WOMAC e OKS, FJS favorevole: valori non riportati nell'abstract. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: la conversione robotica mostra prestazione intraoperatoria riproducibile, pochi aumenti ed esiti precoci favorevoli; servono studi a più lungo termine.",limits:"Cinque serie piccole, senza confronto con la conversione manuale: il contributo del robot non si isola · follow-up medio inferiore a 2 anni · eventi rari (una frattura, due infezioni) non stimabili con precisione · intervalli intorno alle percentuali non riportati.",perte:"Robot MAKO e ROSA, non VELYS, e conversione da UKA, non da tua protesi di partenza. Contesto per la protesi robotica: se un paziente con UKA fallita arriva da te, il dato dice che la conversione robotica è fattibile con pochi aumenti, non che sia migliore della manuale. Cosa fare: nulla."}];
var SUGGQ=[{"k": "kol", "n": "Peter D. Fabricant (Hospital for Special Surgery, New York, USA)", "w": "Stati Uniti: ultimo firmatario dello studio PLUTO sull'LCA transfisario vicino alla maturità (PMID 42877964; afferenza letta nei metadati PubMed). Corrispondenza tecnica con l'LCA nell'adolescente, che segui. Sostituisce Sébastien Lustig (15 ottobre, nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Venerdì 16 ottobre. Oggi nove lavori, una scheda rossa e nessuna arancione. La rossa c'è per regola: è un consensus sul legamento crociato, quello dell'UEFA sul calcio femminile, e non contraddice la tua pratica. Nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi. Il lavoro del giorno è la seconda parte di quel consensus, sulla riabilitazione e sul rientro: ventisei esperti hanno valutato centottanta affermazioni, con accordo su centosettanta. La progressione va a criteri e non a tempi fissi, e la forza del quadricipite è la tappa centrale, accanto a prontezza neuromuscolare e psicologica e a un rientro a fasi. Il limite è che è un consenso di esperti: le soglie numeriche non sono nell'abstract e il testo completo non l'ho aperto. Tocca la tua tensione sul criterio di rientro: conferma la tua simmetria di forza, ma come una tappa fra altre e non come cancello unico. Poi due lavori sul crociato che toccano le tue tecniche. Una coorte di duecentotrentadue ricostruzioni in calciatori professionisti: tredici rotture dell'innesto, cinque virgola sei per cento a circa cento mesi; senza rinforzo laterale dodici virgola nove per cento, con rinforzo quattro virgola cinque, ma la differenza non è significativa e il gruppo senza rinforzo è di soli trentuno pazienti, quindi lo studio è muto sul rinforzo. E lo studio PLUTO su novantuno ragazzi operati a meno di due anni dalla maturità: l'allineamento cambia poco in mediana, ma in una quota fra il sedici e il ventotto per cento cambia in modo rilevante, più spesso verso il valgo. Terzo, una revisione sul legamento patello-femorale mediale: il rientro è riportato fra l'ottantacinque e il cento per cento, ma solo il quattordici-quaranta per cento supera tutti i criteri definiti e il quadricipite resta spesso sotto il novanta per cento. Poi cinque lavori di contesto: la prima parte del consensus UEFA, sulla prevenzione; una coorte di Bordeaux su quattrocentosettantanove operati, in cui il rientro a cinque anni è simile fra i sessi ma le donne ritrovano meno spesso il livello di prima; una metanalisi sulla stimolazione elettrica dopo il crociato, con forza più alta nelle prime settimane e niente oltre i tre mesi; la nota tecnica di Bologna sul menisco laterale ipermobile, con tre nomi della tua rete; e la revisione sulla conversione robotica da protesi monocompartimentale a totale, su cinque piccole serie. La tensione sul criterio di rientro riceve quattro dati laterali; quella sul rinforzo laterale ne riceve uno, senza cambiare. Nella seconda pagina dodici brevi e tre proposte fuori dal solito, fra cui l'intelligenza artificiale per il paziente ortopedico anziano, da Zurigo.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Venerdì sedici ottobre. Nove lavori, una scheda rossa e nessuna arancione. La rossa c'è per regola: un consensus sul crociato, quello UEFA sul calcio femminile."}, {"chi": "B", "t": "E contraddice quello che fai?"}, {"chi": "A", "t": "No. Il lavoro del giorno è la seconda parte: ventisei esperti, centottanta affermazioni, accordo su centosettanta. Il rientro va a criteri e non a tempi fissi, con la forza del quadricipite come tappa centrale."}, {"chi": "B", "t": "Quindi per la tua simmetria di forza?"}, {"chi": "A", "t": "Resta valida, ma come una tappa fra altre: accanto ci sono la prontezza neuromuscolare e quella psicologica, e un rientro a fasi. Il limite è che è un consenso di esperti e le soglie numeriche non sono nell'abstract."}, {"chi": "B", "t": "E sul rinforzo laterale?"}, {"chi": "A", "t": "Una coorte di duecentotrentadue ricostruzioni in calciatori professionisti: tredici rotture dell'innesto. Senza rinforzo dodici virgola nove per cento, con rinforzo quattro virgola cinque, ma la differenza non è significativa e il gruppo senza rinforzo è di trentuno pazienti: lo studio è muto."}, {"chi": "B", "t": "Quindi nessuna conferma e nessuna smentita."}, {"chi": "A", "t": "Esatto. Poi il PLUTO, novantuno ragazzi operati a meno di due anni dalla maturità: l'allineamento cambia poco in mediana, ma in una quota fra il sedici e il ventotto per cento cambia in modo rilevante, più spesso verso il valgo."}, {"chi": "B", "t": "Che cosa ne ricavi per i tuoi casi?"}, {"chi": "A", "t": "Gli autori indicano una radiografia dell'arto intero prima dell'intervento e un controllo fino alla maturità."}, {"chi": "B", "t": "E il resto?"}, {"chi": "A", "t": "Una revisione sul legamento patello-femorale mediale: rientro quasi per tutti, ma solo una minoranza supera tutti i criteri e il quadricipite resta spesso sotto il novanta per cento. Poi una coorte di Bordeaux: stesso rientro a cinque anni fra i sessi, ma le donne ritrovano meno spesso il livello di prima."}, {"chi": "B", "t": "E le note di contesto?"}, {"chi": "A", "t": "La prima parte del consensus UEFA sulla prevenzione, la stimolazione elettrica dopo il crociato, una nota tecnica di Bologna sul menisco laterale ipermobile e la conversione robotica da protesi parziale a totale. Nessuna tensione si è risolta; quella sul criterio di rientro ha quattro dati nuovi."}];
